function card(p){return `<article class="card rv"><div style="position:relative;overflow:hidden"><a class="im" href="#/product/${p.id}" aria-label="${p.name}">${PI(p,p.colors[0],0)}${PI(p,p.colors[p.colors.length-1],1,'h')}</a><button class="wl ${wish.includes(p.id)?'on':''}" data-w="${p.id}" aria-label="Wishlist ${p.name}">${heart}</button><button class="q lab" data-q="${p.id}" ${p.stock?'':'disabled'}>${p.stock?'Add to bag':'Sold out'}</button></div><div class="m"><div><b>${p.name}</b><small>${p.category}</small></div><span>${$f(p.price)}</span></div></article>`}
const grid=l=>`<div class="grid">${l.map(card).join('')}</div>`;
function tile(p,v,col){return `<div class="pi" data-p="${p.id}" data-c="${col||p.colors[0]}" data-v="${v}" style="position:absolute"></div>`}
/* ---------- views ---------- */
function home(){const hero=byId('n19');
const J=[['Culture','The New Language of Style','Dressing now means editing: fewer pieces, each one argued for.','n04','06 Oct 2026'],['Craft','Material / Matter','A week in the Portuguese mill that weaves our poplin, thread by patient thread.','n05','28 Sep 2026'],['Form','Form in Motion','How a seam placed two centimetres lower changes the way a coat moves.','n02','15 Sep 2026'],['Ethos','The Art of Restraint','On the discipline of leaving things out, and why it reads as confidence.','n15','02 Sep 2026']];
window.J=J;
return `<section class="hero" style="padding:0"><div class="art" id="hp">${HS.map((x,i)=>PI(byId(x[0]),byId(x[0]).colors[0],0,'hs'+(i?'':' on'))).join('')}</div><div class="t"><span class="lab">Autumn / Winter 2026</span><span class="lab" id="hl" style="display:block;margin-top:10px;opacity:.55">Look 01 — Women</span><h1><span><i>Live with</i></span><span><i>style.</i></span></h1><p style="max-width:34ch;font-size:16px;opacity:.8;margin:0 0 30px">Modern essentials, precisely considered.</p><a class="btn lab" href="#/shop/all" data-mag>Shop the collection →</a> <a class="btn lab" href="#/shop/women" style="margin-left:8px">Women</a> <a class="btn lab" href="#/shop/men" style="margin-left:8px">Men</a><div class="hd2" aria-hidden="true">${HS.map(()=>'<i></i>').join('')}</div></div></section>
<div class="mq" aria-hidden="true"><div>${Array(10).fill('<span>Vérane</span><span class="lab" style="font-style:normal">Live with style</span><span>Designed with intent</span><span class="lab" style="font-style:normal">AW26</span>').join('')}</div></div>
${strip()}<section><div class="sh rv"><div><span class="lab">01 — New arrivals</span><h2>The new season</h2></div><a class="lab ul" href="#/shop/new">View all</a></div>${grid(['v14','v03','v18','n12','v09','v13','w17','v15'].map(byId))}</section>
<section class="ed"><div class="im rv">${tile(byId('n12'),0,'Green')}</div><div class="rv"><span class="lab">02 — Featured collection</span><h2 style="margin-top:16px">The <em>Tailoring</em> Edit</h2><p style="max-width:44ch;opacity:.7;margin:0 0 30px">Shoulders softened, linings removed, proportions held. Suiting for people who would rather be remembered than noticed.</p><a class="btn lab" href="#/shop/all?cat=Suits,Trousers" data-mag>Explore the edit</a></div></section>
<section style="padding-block:clamp(90px,14vw,220px);text-align:center"><span class="lab">03 — Editorial campaign</span><p class="serif rv" style="font-size:clamp(40px,8vw,128px);margin:20px auto 0;max-width:15ch">Less, <em style="color:var(--mut)">but exact.</em></p></section>
<section style="padding-top:0"><div class="sh rv"><div><span class="lab">04 — Women · Men</span><h2>Two wardrobes</h2></div></div><div class="split rv"><a class="tile" href="#/shop/women" style="background:#ddd5c4"><div class="pi" data-p="v18" data-c="Sky" data-v="0" style="position:absolute;inset:0"></div><h3>Women</h3><span class="lab">Shop women →</span></a><a class="tile" href="#/shop/men" style="background:#ddd5c4"><div class="pi" data-p="v03" data-c="Burgundy" data-v="0" style="position:absolute;inset:0"></div><h3>Men</h3><span class="lab">Shop men →</span></a></div></section>
<div class="bm" aria-hidden="true"><div>${Array(6).fill('<span>Women</span><span>Men</span>').join('')}</div></div><section id="women"><div class="sh rv"><div><span class="lab">For her</span><h2>Women</h2></div><a class="lab ul" href="#/shop/women">Shop women</a></div>${grid(['v14','v18','v15','v09','w17','v07','v12','v06'].map(byId))}</section><section id="men" style="padding-top:0"><div class="sh rv"><div><span class="lab">For him</span><h2>Men</h2></div><a class="lab ul" href="#/shop/men">Shop men</a></div>${grid(['v03','v04','v13','v11','n12','n18','n07','v05'].map(byId))}</section><section class="ey" id="eyewear"><div class="eyh rv"><div><span class="lab" style="color:var(--gold)">06 — Eyewear</span><h2>The vision edit</h2></div><p>Chrome wraps, hand-finished acetate and sculpted shields. Frames that speak before you do.</p><a class="btn lab" href="#/shop/eyewear" data-mag>Shop eyewear →</a></div><div class="eys"><div class="eyf rv" id="eyf" aria-label="Eyewear spotlight">${EY.map((id,i)=>PI(byId(id),byId(id).colors[0],0,'es'+(i?'':' on'))).join('')}<div class="eyc lab" id="eyl"></div></div><div class="eyg">${['e02','e17','e13','e08','e05','e16'].map(i=>card(byId(i))).join('')}</div></div></section><section class="wt" id="watches"><div class="eyh rv"><div><span class="lab">07 — Watches</span><h2>The time edit</h2></div><p>Skeleton cases, sapphire bezels and engraved dials. Pieces built to be passed on.</p><a class="btn lab" href="#/shop/watches" data-mag>Shop watches →</a></div><div class="wtc rv" aria-hidden="true">${[['New York','America/New_York'],['London','Europe/London'],['Dubai','Asia/Dubai'],['Tokyo','Asia/Tokyo']].map(c=>`<div><span class="lab">${c[0]}</span><b data-tz="${c[1]}">--:--:--</b></div>`).join('')}</div><div class="wtr" id="wtr">${['t01','t02','t05','t13','t16','t17','t03','t18'].map((id,i)=>{const p=byId(id);return `<a class="wti" href="#/product/${id}"><div class="im">${PI(p,p.colors[0],0)}<span class="wn">${String(i+1).padStart(2,'0')}</span></div><div class="m"><b>${p.name}</b><span>${$f(p.price)}</span></div></a>`}).join('')}</div><div class="wta"><button id="wtp" class="lab" aria-label="Previous">←</button><button id="wtn" class="lab" aria-label="Next">→</button></div></section><section class="fr" id="fragrance"><div class="frh rv"><span class="lab" style="color:var(--gold)">08 — Fragrance</span><h2>Scent, <em>composed.</em></h2><p>Four families of accord, bottled in glass and gold. Choose a family; hover a flacon to see it in full.</p></div><div class="fre"><a class="frf rv" id="frf" href="#/shop/fragrance" aria-label="Featured fragrance"></a><div class="frt"><div class="frtabs" role="tablist">${FAM.map(f=>`<button class="frtab" role="tab">${f[0]}</button>`).join('')}</div><div class="frg" id="frg"></div><a class="btn lab" href="#/shop/fragrance" data-mag style="margin-top:32px">Shop all fragrance →</a></div></div></section><section style="padding-top:0"><div class="sh rv"><div><span class="lab">05 — Outerwear</span><h2>The outer layer</h2></div><a class="lab ul" href="#/shop/all?cat=Jackets">View all</a></div>${grid(P.filter(p=>p.category=='Jackets').slice(0,4))}</section>
<section style="padding-top:0"><div class="sh rv"><div><span class="lab">06 — Bestsellers</span><h2>Held in rotation</h2></div></div>${grid(['v08','v04','v12','v11'].map(byId))}</section>
<section style="background:#ebe5d8"><span class="lab">07 — Lookbook</span><div class="look" style="margin-top:36px"><div class="a rv">${tile(byId('n18'),0,'Burgundy')}</div><div class="b rv">${tile(byId('n09'),0,'Charcoal')}</div><div class="c rv">${tile(byId('v09'),0,'Orange')}</div><div class="d rv">${tile(byId('v06'),0,'Orange')}</div><p class="big rv" style="margin:6vw 0 0">Cloth, light, <em>and the quiet between.</em></p></div></section>
<section><div class="story"><div class="im rv" style="position:relative">${tile(byId('n05'),0,'Navy')}</div><div class="rv"><span class="lab">08 — Brand story</span><h2 class="serif" style="font-size:clamp(44px,7vw,110px);margin:16px 0 24px">Designed with intent.</h2><p>VÉRANE began with one rule: nothing is added unless it earns its place. Every pattern is cut, tested and recut until the garment stops asking for attention.</p><p>We work with small mills in Portugal, Italy and Japan, and make in editions we can stand behind. The result is a wardrobe that gets quieter, and better, with time.</p></div></div></section>
<section id="journal" style="padding-top:0"><div class="sh rv"><div><span class="lab">09 — Journal</span><h2>Notes &amp; essays</h2></div></div><div class="jr">${J.map((j,i)=>`<button class="rv" data-j="${i}"><div class="im" style="position:relative">${tile(byId(j[3]),i%2?1:0,byId(j[3]).colors[0])}</div><span class="lab" style="color:var(--mut)">${j[0]} · ${j[4]}</span><h3>${j[1]}</h3><p>${j[2]}</p><span class="lab ul">Read story</span></button>`).join('')}</div></section>
<section style="padding-block:clamp(40px,6vw,80px);border-block:1px solid var(--line);margin-bottom:clamp(40px,6vw,80px)"><div class="tr rv">${[['Complimentary shipping','On orders over $250, worldwide'],['Thirty-day returns','Unworn, in original packaging'],['Secure payment','Encrypted, every transaction'],['Made with intent','Small editions, honest cloth']].map(t=>`<div><span class="lab">${t[0]}</span><p>${t[1]}</p></div>`).join('')}</div></section><section id="contact" style="padding-top:0"><div class="sh rv"><div><span class="lab">11 — Contact</span><h2>The atelier</h2></div></div><div class="ct rv"><a href="mailto:jadonvikram48@gmail.com"><span class="lab">Email</span><b>jadonvikram48@gmail.com</b></a><a href="tel:+919511537577"><span class="lab">Phone / WhatsApp</span><b>+91 95115 37577</b></a><a href="https://instagram.com/win.automation.ai" target="_blank" rel="noopener"><span class="lab">Instagram</span><b>@win.automation.ai</b></a></div></section><section class="nl"><span class="lab">12 — Newsletter</span><h2 class="serif" style="font-size:clamp(40px,6vw,90px);margin:16px 0 0">Letters, occasionally.</h2><form id="nf" novalidate><input type="email" id="ne" placeholder="Email address" aria-label="Email address"><button class="lab" style="padding:0 0 0 20px">Subscribe</button></form><p id="nm" role="status"></p></section>`+foot()}
function foot(){return `<footer><div><div style="margin-bottom:14px">${MK}<div class="logo" style="align-items:flex-start;padding:0;margin-top:14px"><span>VÉRANE</span><small style="padding-left:0">MAISON</small></div></div><p style="color:var(--mut);max-width:30ch">Live with style. Modern essentials, precisely considered.</p></div><div><h4 class="lab">Shop</h4><a href="#/shop/new">New In</a><a href="#/shop/women">Women</a><a href="#/shop/men">Men</a><a href="#/shop/accessories">Accessories</a><a href="#/shop/eyewear">Eyewear</a><a href="#/shop/watches">Watches</a><a href="#/shop/fragrance">Fragrance</a></div><div><h4 class="lab">Care</h4><a href="#/info/shipping">Shipping</a><a href="#/info/returns">Returns</a><a href="#/info/size">Size guide</a></div><div><h4 class="lab">House</h4><a href="#journal">Journal</a><a href="#/info/story">Our story</a><a href="#/info/contact">Contact</a><a href="https://instagram.com/win.automation.ai" target="_blank" rel="noopener">Instagram</a></div><div class="fb lab"><span>© 2026 VÉRANE</span><span>Privacy · Terms</span></div></footer>`}
const F={cat:[],size:[],color:[],max:15000,avail:false,sort:'Featured',g:'all',newOnly:false};
function shop(seg,q){F.g='all';F.newOnly=false;F.cat=[];if(seg=='women')F.g='w';if(seg=='men')F.g='m';if(seg=='new')F.newOnly=true;if(seg=='eyewear')F.cat=['Eyewear'];if(seg=='watches')F.cat=['Watches'];if(seg=='fragrance')F.cat=['Fragrance'];if(seg=='accessories')F.cat=['Bags','Accessories','Sneakers','Boots'];if(q.cat)F.cat=q.cat.split(',');
const t={all:'All products',new:'New arrivals',women:'Women',men:'Men',accessories:'Accessories',eyewear:'Eyewear',watches:'Watches',fragrance:'Fragrance'}[seg]||'All products';document.title='VÉRANE — '+t;
const sizes=[...new Set(P.flatMap(p=>p.sizes))],cols=Object.keys(C);
return `<div class="pg"><span class="lab" style="color:var(--mut)">VÉRANE / Shop</span><div class="sh" style="margin-top:8px"><h2 class="serif" style="font-size:clamp(44px,7vw,100px);margin:0">${t}</h2><div style="display:flex;gap:10px;align-items:center"><button class="btn lab fbtn" id="fo">Filters</button><label class="lab">Sort <select id="so">${['Featured','Newest','Price low → high','Price high → low'].map(s=>`<option ${F.sort==s?'selected':''}>${s}</option>`).join('')}</select></label></div></div>
<div class="lab" style="display:flex;gap:26px;margin:0 0 26px;flex-wrap:wrap">${[['All','all'],['Women','women'],['Men','men'],['New','new'],['Accessories','accessories'],['Eyewear','eyewear'],['Watches','watches'],['Fragrance','fragrance']].map(t=>`<a href="#/shop/${t[1]}" class="ul" style="${seg==t[1]?'':'border-color:transparent;color:var(--mut)'}">${t[0]}</a>`).join('')}</div><div class="shop"><div class="fl" id="fl"><button class="btn lab fbtn" id="fc" style="margin-bottom:10px">Show results</button><h4 class="lab">Category</h4>${CL.map(c=>`<label><input type="checkbox" data-f="cat" value="${c}" ${F.cat.includes(c)?'checked':''}>${c}</label>`).join('')}<h4 class="lab">Size</h4>${sizes.map(c=>`<label style="display:inline-flex;margin-right:10px"><input type="checkbox" data-f="size" value="${c}">${c}</label>`).join('')}<h4 class="lab">Colour</h4>${cols.map(c=>`<label><input type="checkbox" data-f="color" value="${c}"><i class="sw" style="background:${C[c]}"></i>${c}</label>`).join('')}<h4 class="lab">Price up to <span id="pv">$15,000</span></h4><input type="range" id="pr" min="100" max="15000" step="100" value="15000" aria-label="Maximum price"><h4 class="lab">Availability</h4><label><input type="checkbox" id="av">In stock only</label></div>
<div><p id="rc" class="lab" style="color:var(--mut);margin:0 0 20px"></p><div id="rs" class="grid" style="grid-template-columns:repeat(3,1fr)"></div></div></div></div>`+foot()}
function results(){let l=P.filter(p=>(F.g=='all'||p.gender==F.g||p.gender=='u')&&(!F.newOnly||p.isNew)&&(!F.cat.length||F.cat.includes(p.category))&&(!F.size.length||p.sizes.some(s=>F.size.includes(s)))&&(!F.color.length||p.colors.some(c=>F.color.includes(c)))&&p.price<=F.max&&(!F.avail||p.stock>0));
if(F.sort=='Featured')l=[...l].sort((a,b)=>!!IMG[b.id]-!!IMG[a.id]);if(F.sort=='Newest')l=[...l].sort((a,b)=>b.id.localeCompare(a.id));if(F.sort.startsWith('Price low'))l=[...l].sort((a,b)=>a.price-b.price);if(F.sort.startsWith('Price high'))l=[...l].sort((a,b)=>b.price-a.price);
$('#rc').textContent=l.length+' pieces';$('#rs').innerHTML=l.length?l.map(card).join(''):`<div class="empty"><h3>Nothing matches.</h3><p>Loosen a filter to see more of the collection.</p><button class="btn lab" id="clr">Clear filters</button></div>`;hydrate($('#rs'));reveal()}
let sel={};
function product(id){const p=byId(id);if(!p)return nf();document.title=`${p.name} — VÉRANE`;sel={id,size:null,color:p.colors[0],qty:1};
const rel=P.filter(x=>x.category==p.category&&x.id!=id).concat(P.filter(x=>x.category!=p.category)).slice(0,4);
const ld=JSON.stringify({'@context':'https://schema.org','@type':'Product',name:p.name,description:p.description,category:p.category,offers:{'@type':'Offer',price:p.price,priceCurrency:'USD',availability:p.stock?'https://schema.org/InStock':'https://schema.org/OutOfStock'}});
return `<script type="application/ld+json">${ld}<\/script><div class="pg"><a class="lab" style="color:var(--mut)" href="#/shop/all">← Shop</a><div class="pd" style="margin-top:20px"><div class="gal" id="gl"></div><div class="info"><span class="lab" style="color:var(--mut)">${p.category}</span><h1>${p.name}</h1><p style="font-size:20px;margin:0 0 16px">${$f(p.price)}</p><p>${p.description}</p>
<div class="lab">Colour — <span id="cn">${p.colors[0]}</span></div><div class="opt" id="oc">${p.colors.map((c,i)=>`<button class="cs ${i?'':'on'}" data-c="${c}" style="background:${C[c]}" aria-label="${c}"></button>`).join('')}</div>
<div class="lab" style="display:flex;justify-content:space-between">Size <a class="ul" href="#/info/size">Size guide</a></div><div class="opt" id="os">${p.sizes.map(s=>`<button data-s="${s}" ${p.stock?'':'disabled'}>${s}</button>`).join('')}</div>
<div style="display:flex;gap:10px;margin-bottom:26px"><div class="qty"><button id="qm" aria-label="Decrease">−</button><span id="qn">1</span><button id="qp" aria-label="Increase">+</button></div><button class="btn fill lab" id="ab2" style="flex:1;justify-content:center" ${p.stock?'':'disabled'}>${p.stock?'Add to bag':'Sold out'}</button><button class="wl" style="position:static;border:1px solid var(--line);width:50px;height:auto" data-w="${p.id}" aria-label="Wishlist">${heart}</button></div>
<details open><summary class="lab">Material</summary><p>${p.material}</p></details><details><summary class="lab">Details</summary><p>Relaxed through the body, clean finishing, concealed fastenings. Model wears size M.</p></details><details><summary class="lab">Shipping</summary><p>Complimentary express delivery over $250. Dispatched within two working days.</p></details><details><summary class="lab">Returns</summary><p>Thirty days, unworn, in original packaging.</p></details></div></div>
<h2 class="serif" style="font-size:clamp(36px,5vw,64px);margin:90px 0 30px">You may also like</h2>${grid(rel)}</div>`+foot()}
function nf(){document.title='Not found — VÉRANE';return `<div class="pg" style="min-height:80vh;display:grid;place-items:center;text-align:center"><div><span class="lab">404</span><h1 class="serif" style="font-size:clamp(48px,9vw,120px);margin:10px 0 20px">Not on the rail.</h1><p style="color:var(--mut)">This page has moved, or never existed.</p><a class="btn lab" href="#/shop/all">Return to the shop</a></div></div>`+foot()}
const INFO={shipping:['Shipping','Complimentary express delivery on orders over $250, worldwide. Orders are dispatched within two working days in recycled, minimal packaging.'],returns:['Returns','Return any unworn piece within thirty days for a full refund to your original payment method.'],size:['Size guide','Tops: XS 34–35in chest, S 36–37, M 38–40, L 41–43, XL 44–46. Trousers follow waist in inches. Footwear is EU sizing; size up for half sizes.'],story:['Our story','VÉRANE makes considered wardrobe essentials in small editions, with mills we know by name.'],contact:['Contact','Email jadonvikram48@gmail.com, call or WhatsApp +91 95115 37577, or message us on Instagram @win.automation.ai. We reply within one working day.']};
function info(k){const i=INFO[k];if(!i)return nf();document.title=i[0]+' — VÉRANE';return `<div class="pg" style="max-width:760px;margin:auto"><span class="lab" style="color:var(--mut)">VÉRANE</span><h1 class="serif" style="font-size:clamp(44px,7vw,96px);margin:10px 0 26px">${i[0]}</h1><p style="font-size:17px">${i[1]}</p><a class="btn lab" href="#/shop/all" style="margin-top:20px">Continue shopping</a></div>`+foot()}
/* ---------- router ---------- */
function route(){const h=location.hash.slice(1)||'/';if(h.startsWith('journal')||h=='journal'){if(!$('#journal')){location.hash='#/';return}$('#journal').scrollIntoView({behavior:'smooth'});return}
const [path,qs]=h.split('?'),q=Object.fromEntries(new URLSearchParams(qs||'')),s=path.split('/').filter(Boolean),app=$('#app');
let html;if(!s.length){document.title='VÉRANE — Live With Style';html=home()}else if(s[0]=='shop')html=shop(s[1]||'all',q);else if(s[0]=='product')html=product(s[1]);else if(s[0]=='info')html=info(s[1]);else html=nf();
const go=()=>{app.innerHTML=html;scrollTo(0,0);hydrate(app);reveal();bindPage(s);hdr();closeAll()};
app.style.transition='opacity .35s';app.style.opacity=0;setTimeout(()=>{go();app.style.opacity=1},app.innerHTML?260:0)}
function bindPage(s){if(s[0]=='shop'){$('#so').onchange=e=>{F.sort=e.target.value;results()};$$('[data-f]').forEach(i=>i.onchange=()=>{F[i.dataset.f]=$$(`[data-f=${i.dataset.f}]:checked`).map(x=>x.value);results()});$('#pr').oninput=e=>{F.max=+e.target.value;$('#pv').textContent=$f(F.max);results()};$('#av').onchange=e=>{F.avail=e.target.checked;results()};$('#fo').onclick=()=>$('#fl').classList.add('open');$('#fc').onclick=()=>$('#fl').classList.remove('open');results()}
if(s[0]=='product'&&byId(s[1]))bindProd();$('#nf')&&($('#nf').onsubmit=e=>{e.preventDefault();const v=$('#ne').value.trim(),m=$('#nm');if(!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v)){m.textContent='Please enter a valid email address.';return}m.textContent='Thank you. Your first letter arrives soon.';$('#ne').value=''});
const hp=$('#hp');clearInterval(window._hs);clearInterval(window._es);if($('#eyf'))EYE();clearInterval(window._wt);clearInterval(window._wa);if($('#wtr'))WT();if($('#frg'))FR();if(hp){HERO();onscroll=()=>{hdr();if(scrollY<innerHeight)hp.style.transform=`translateY(${scrollY*.12}px) scale(${1+scrollY/6000})`}}else onscroll=hdr}
function bindProd(){const p=byId(sel.id);const gl=()=>{$('#gl').innerHTML=[0,1,2,3,4].map(v=>`<div class="z" data-z>${PI(p,sel.color,v)}</div>`).join('');hydrate($('#gl'));$$('[data-z]').forEach(z=>{z.onclick=()=>z.classList.toggle('zm');z.onmousemove=e=>{if(z.classList.contains('zm')){const r=z.getBoundingClientRect(),i=$('.pi',z);i.style.transformOrigin=`${(e.clientX-r.left)/r.width*100}% ${(e.clientY-r.top)/r.height*100}%`}};z.onmouseleave=()=>z.classList.remove('zm')})};gl();
$$('#oc button').forEach(b=>b.onclick=()=>{sel.color=b.dataset.c;$$('#oc button').forEach(x=>x.classList.toggle('on',x==b));$('#cn').textContent=sel.color;gl()});
$$('#os button').forEach(b=>b.onclick=()=>{sel.size=b.dataset.s;$$('#os button').forEach(x=>x.classList.toggle('on',x==b))});
if(p.sizes.length==1&&p.stock){sel.size=p.sizes[0];$('#os button').classList.add('on')}
$('#qm').onclick=()=>{sel.qty=Math.max(1,sel.qty-1);$('#qn').textContent=sel.qty};$('#qp').onclick=()=>{sel.qty=Math.min(9,sel.qty+1);$('#qn').textContent=sel.qty};
$('#ab2').onclick=()=>{if(!sel.size){toast('Please select a size.');return}add(p.id,sel.size,sel.color,sel.qty)}}
/* ---------- cart ---------- */
function add(id,size,color,qty=1){const k=id+size+color,e=cart.find(i=>i.k==k);e?e.qty=Math.min(9,e.qty+qty):cart.push({k,id,size,color,qty});save();drawCart();open('dr')}
function save(){ls.s('nx-cart',cart);ls.s('nx-wish',wish);$('#cc').textContent=cart.reduce((a,i)=>a+i.qty,0);$('#wc').textContent=wish.length?`(${wish.length})`:''}
function drawCart(){const dr=$('#dr'),sub=cart.reduce((a,i)=>a+byId(i.id).price*i.qty,0),rec=P.filter(p=>!cart.some(i=>i.id==p.id)).slice(2,10);
dr.innerHTML=`<div class="dh"><span class="lab">Bag (${cart.reduce((a,i)=>a+i.qty,0)})</span><button class="lab" data-x>Close</button></div><div class="db">${cart.length?cart.map(i=>{const p=byId(i.id);return `<div class="li"><div class="im">${PI(p,i.color,0)}</div><div><b style="font-weight:400">${p.name}</b><small>${i.color} · ${i.size}</small><div>${$f(p.price)}</div><div style="display:flex;align-items:center"><div class="qty"><button data-ci="${i.k}" data-d="-1" aria-label="Decrease">−</button><span>${i.qty}</span><button data-ci="${i.k}" data-d="1" aria-label="Increase">+</button></div><button class="rm" data-rm="${i.k}">Remove</button></div></div></div>`}).join(''):`<div class="empty" style="padding:60px 0"><h3>Your bag is empty.</h3><p style="color:var(--mut)">Begin with something new.</p><a class="btn lab" href="#/shop/new" data-x>Shop new in</a></div>`}
<div style="padding:26px 0"><div class="lab" style="margin-bottom:12px">You may also like</div><div class="rec">${rec.map(p=>`<a href="#/product/${p.id}" data-x><div class="im">${PI(p,p.colors[0],0)}</div><small>${p.name}<br>${$f(p.price)}</small></a>`).join('')}</div></div></div>${cart.length?`<div class="df"><div style="display:flex;justify-content:space-between;margin-bottom:14px"><span class="lab">Subtotal</span><b style="font-weight:400">${$f(sub)}</b></div><button class="btn fill lab" style="width:100%;justify-content:center" id="co">Checkout</button></div>`:''}`;hydrate(dr);
$$('[data-ci]',dr).forEach(b=>b.onclick=()=>{const i=cart.find(x=>x.k==b.dataset.ci);i.qty+=+b.dataset.d;if(i.qty<1)cart=cart.filter(x=>x!=i);if(i.qty>9)i.qty=9;save();drawCart()});
$$('[data-rm]',dr).forEach(b=>b.onclick=()=>{cart=cart.filter(x=>x.k!=b.dataset.rm);save();drawCart()});
$('#co')&&($('#co').onclick=()=>{cart=[];save();drawCart();toast('Thank you. Your order is confirmed.');closeAll()})}
function wishView(){const l=wish.map(byId).filter(Boolean);$('#dr').innerHTML=`<div class="dh"><span class="lab">Wishlist (${l.length})</span><button class="lab" data-x>Close</button></div><div class="db">${l.length?l.map(p=>`<div class="li"><a class="im" href="#/product/${p.id}" data-x>${PI(p,p.colors[0],0)}</a><div><b style="font-weight:400">${p.name}</b><small>${p.category}</small><div>${$f(p.price)}</div><button class="rm" data-w="${p.id}" style="margin:8px 0 0">Remove</button></div></div>`).join(''):`<div class="empty" style="padding:60px 0"><h3>Nothing saved yet.</h3><p style="color:var(--mut)">Tap the heart on any piece to keep it here.</p></div>`}</div>`;hydrate($('#dr'));open('dr')}
