function search(){const s=$('#sr');s.innerHTML=`<div style="display:flex;justify-content:space-between"><span class="logo" style="padding:0;align-items:flex-start"><span>VÉRANE</span><small style="padding-left:0">MAISON</small></span><button class="lab" data-x>Close</button></div><input id="si" placeholder="Search" aria-label="Search" autocomplete="off"><div id="sx"></div>`;open('sr');setTimeout(()=>$('#si').focus(),300);const draw=v=>{v=v.trim().toLowerCase();if(!v){$('#sx').innerHTML=`<div class="lab" style="margin-bottom:12px">${recent.length?'Recent searches':'Popular'}</div>${(recent.length?recent:['Jacket','Suit','Denim','Shirt','Dress']).map(r=>`<button class="chip" data-r="${r}">${r}</button>`).join('')}<div class="lab" style="margin:26px 0 12px">Categories</div>${CL.map(c=>`<a class="chip" href="#/shop/all?cat=${c}" data-x>${c}</a>`).join('')}`;$$('[data-r]').forEach(b=>b.onclick=()=>{$('#si').value=b.dataset.r;draw(b.dataset.r)});return}
const l=P.filter(p=>(p.name+p.category+p.colors.join()+p.material).toLowerCase().includes(v)),cats=CL.filter(c=>c.toLowerCase().includes(v));$('#sx').innerHTML=(cats.length?`<div style="margin-bottom:20px">${cats.map(c=>`<a class="chip" href="#/shop/all?cat=${c}" data-x>${c}</a>`).join('')}</div>`:'')+(l.length?`<div class="sr">${l.map(p=>`<a href="#/product/${p.id}" data-x data-sv="${v}"><div class="im">${PI(p,p.colors[0],0)}</div><div style="padding-top:8px">${p.name}<br><span style="color:var(--mut)">${$f(p.price)}</span></div></a>`).join('')}</div>`:`<div class="empty"><h3>No results for “${v.replace(/[<>&]/g,'')}”.</h3><p style="color:var(--mut)">Try a category such as coat, denim or boot.</p></div>`);hydrate($('#sx'))};draw('');$('#si').oninput=e=>draw(e.target.value);$('#sx').onclick=e=>{const a=e.target.closest('[data-sv]');if(a){recent=[a.dataset.sv,...recent.filter(x=>x!=a.dataset.sv)].slice(0,5);ls.s('nx-rec',recent)}}}
function mega(on,k){const m=$('#mega'),hd=$('#hd');if(!on){m.classList.remove('on');hd.classList.remove('mega');return}
const W=['Dresses','Suits','Denim','Knitwear','Jackets','Trousers'],M=['Shirts','Polos','Suits','Trousers','Jackets'],A=['Accessories','Sneakers'];const lk=(l,g='all')=>l.map(c=>`<a href="#/shop/${g}?cat=${c}">${c}</a>`).join('');
m.innerHTML=`<div><h4 class="lab">Women</h4><a href="#/shop/women">All women</a>${lk(W,'women')}</div><div><h4 class="lab">Men</h4><a href="#/shop/men">All men</a>${lk(M,'men')}</div><div><h4 class="lab">Accessories</h4><a href="#/shop/accessories">All accessories</a>${lk(A)}</div><div><h4 class="lab">Collections</h4><a href="#/shop/eyewear">Eyewear</a><a href="#/shop/watches">Watches</a><a href="#/shop/fragrance">Fragrance</a><a href="#/shop/new">New arrivals</a><a href="#/shop/all?cat=Suits,Trousers">The Tailoring Edit</a><a href="#/shop/all?cat=Knitwear,Jackets">Winter Cloth</a></div><a href="#/product/n07" style="color:inherit"><div class="im" style="aspect-ratio:4/5;position:relative;overflow:hidden">${PI(byId('n07'),'Ink',0)}</div><span class="lab" style="display:block;margin-top:8px">The Leather Zip Jacket</span></a>`;hydrate(m);m.classList.add('on');hd.classList.add('mega')}
function reveal(){const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{rootMargin:'0px 0px -6% 0px'});$$('.rv:not(.in)').forEach(e=>io.observe(e))}
