function WT(){const r=$('#wtr');if(!r)return;const step=()=>{const c=$('.wti',r);return c?c.getBoundingClientRect().width+16:300},go=d=>{if(d>0&&r.scrollLeft+r.clientWidth>=r.scrollWidth-4)r.scrollTo({left:0,behavior:'smooth'});else if(d<0&&r.scrollLeft<=4)r.scrollTo({left:r.scrollWidth,behavior:'smooth'});else r.scrollBy({left:d*step(),behavior:'smooth'})};$('#wtn').onclick=()=>go(1);$('#wtp').onclick=()=>go(-1);let hold=false;r.onmouseenter=()=>hold=true;r.onmouseleave=()=>hold=false;r.ontouchstart=()=>hold=true;const tz=()=>$$('[data-tz]').forEach(e=>{try{e.textContent=new Date().toLocaleTimeString('en-GB',{timeZone:e.dataset.tz,hour12:false})}catch(_){}});tz();window._wt=setInterval(tz,1000);window._wa=setInterval(()=>{if(!hold&&!document.hidden&&!matchMedia('(prefers-reduced-motion:reduce)').matches)go(1)},2600)}
