const cu=$('#cur');if(matchMedia('(hover:hover) and (pointer:fine)').matches){let x=0,y=0,cx=0,cy=0;addEventListener('mousemove',e=>{x=e.clientX;y=e.clientY;cu.classList.toggle('big',!!e.target.closest('.card .im,.tile,.jr button'));const m=e.target.closest('[data-mag]');if(m){const r=m.getBoundingClientRect();m.style.transform=`translate(${(e.clientX-r.left-r.width/2)*.12}px,${(e.clientY-r.top-r.height/2)*.2}px)`}});addEventListener('mouseout',e=>{const m=e.target.closest&&e.target.closest('[data-mag]');if(m)m.style.transform=''});(function l(){cx+=(x-cx)*.2;cy+=(y-cy)*.2;cu.style.transform=`translate(${cx-6}px,${cy-6}px)`;requestAnimationFrame(l)})()}
